    for (size_t i = 0; i < n; ++i) {
        unsigned __int128 sum = (unsigned __int128)lhs[i] + rhs[i] + carry_in;
        result[i] = (uint64_t)sum;
        carry_in = (uint64_t)(sum >> 64);
    }
}
