            int mismatch_idx = -1;
            for (size_t i = 0; i < NUM_ELEMENTS; ++i) {
                if (ctx.output[i] != shared_data->golden_output[i]) { mismatch_idx = (int)i; break; }
            }
            char ctx_msg[200];
