122	/* Log-uniform random block length in [MIN_BLOCK, MAX_BLOCK]: pick the
123	 * exponent uniformly so every decade (L1/L2/L3/DRAM scale) is equally
124	 * likely, then the mantissa uniformly inside it. Result is 64-byte
125	 * aligned (whole cache lines).
126	 */
127	static size_t random_block_len(void)
128	{
129	    /* exponents: 64=2^6 .. 2^21 → 16 buckets for the log scale */
130	    int bucket = (int)(random32() % 16);          /* 0..15 */
131	    size_t len = (size_t)1 << (6 + bucket);
132	    if (len > MAX_BLOCK)
