    name = re.search(r'DECLARE_TEST\((\w+)', s).group(1)
    m = re.search(r'static int (\w+)_run\(struct test \*test, int cpu\) \{\n(.*?)\n\}\n', s, re.S)
    if not m: return f"RUN MISS {path}"
    body = m.group(2)
    tl = re.search(r'(    TEST_LOOP\(test, 256\) \{\n)(.*?)(\n    \})\n', body, re.S)
    if not tl: return f"LOOP MISS {path}"
    gf = re.search(r'static void (\w+)_compute_golden\(', s)
    if not gf: return f"GOLDEN MISS {path}"
    golden_fn = gf.group(1) + "_compute_golden"
    st = re.search(r'struct (\w+) \*d = ', body)
    if not st: return f"STRUCT MISS {path}"
    struct_ty = st.group(1)

    pre = body[:tl.start()]
    post = body[tl.end():]
    inject_pre = """
    /* randomization hardening H6': per-thread plaintext + golden, re-rolled
     * every iteration (thread-safe: shared d is only read; the shallow
     * struct copy points plaintext/golden_ciphertext at thread-local
     * buffers, and compute_golden writes only into the copy). */
    struct %s local_d;
    uint8_t *plain = (uint8_t *)malloc(d->datasize);
    uint8_t *gold = (uint8_t *)malloc(d->datasize);
    if (!plain || !gold) {
        free(ciphertext); free(decrypted); free(mac);
        free(plain); free(gold);
        return EXIT_FAILURE;
    }
    memcpy(&local_d, d, sizeof(local_d));
    local_d.plaintext = plain;
    local_d.golden_ciphertext = gold;
""" % struct_ty
    inject_loop = """
        /* re-roll: fresh plaintext + same-iteration golden (independent
         * EVP path recomputed for this thread's data) */
        memset_random(local_d.plaintext, d->datasize);
        %s(&local_d);
""" % golden_fn
    # ALL d-> references inside the loop body → local_d. (local_d is a
    # shallow copy: keys/ivs hold the same shared values, while
    # plaintext/golden_* point at this thread's buffers.)
    new_loop_body = re.sub(r'\bd->', 'local_d.', tl.group(2))
